parameters.style:
/* Digital Bricks Training — the page ground and the pointer. The lesson CSS is the kit's stylesheet. */
html, body { background: var(--background); color: var(--foreground); font-family: var(--font-sans); }
.pressable { cursor: pointer; }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; animation: none !important; } }
/* TASK-L185: the page held while the current privacy notice is answered. display:none, so it is out of
   the layout, the tab order and the accessibility tree, while the router behind it stays mounted. */
.dbt-pages-held { display: none !important; }

parameters.functionScript:
/*
 * THE NOTICE GATE (TASK-L185 §2), beside the sign-in gate and deliberately not
 * folded into it: that one decides WHERE a person may go, this one decides
 * WHETHER the page they are on may be drawn yet.
 *
 * Signed in and not on the CURRENT notice → the page is HELD (hidden, still
 * mounted) and the acceptance screen renders in its place. Equality, never "at
 * least" (the product's L53): a changed notice asks everybody again. Nothing is
 * back-filled, so an account that never accepted has no version and is asked.
 *
 * NEVER HELD: the notice itself, settings (declining must never take away the
 * way out — L54), sign-in, and the kit's specimen. Staff are asked too: the
 * notice describes what a coach's account holds.
 *
 * NONE OF THIS IS WHAT PROTECTS A WRITE. capture and finishStep refuse under a
 * stale version on the server; this decides what the browser DRAWS. While the
 * notice's version has not arrived from Data/Strings nothing is held — the
 * gate acts on an answer, never on "not loaded yet" (the roles rule above).
 */
const EXEMPT = ['Pages/Privacy', 'Pages/Settings', 'Pages/Sign in', 'Pages/Palette'];
const page = String(Inputs.page || '').replace(/^\/+/, '');
const signedIn = Inputs.signedIn === true;
const version = Inputs.privacy && typeof Inputs.privacy === 'object' ? String(Inputs.privacy.version || '') : '';
let hold = false;
if (page && signedIn && version && EXEMPT.indexOf(page) === -1) {
  const u = typeof Noodl !== 'undefined' && Noodl.Users ? Noodl.Users.Current : undefined;
  const accepted = u && u.Properties && typeof u.Properties.get === 'function' ? u.Properties.get('privacyVersion') : undefined;
  hold = accepted !== version;
}
Outputs.hold = hold;
Outputs.pagesClass = hold ? 'dbt-pages dbt-pages-held' : 'dbt-pages';

// TASK-L185: the User node says its account changed with a SIGNAL (`changed`), and
// the notice gate must re-read `privacyVersion` when it does — a stored session is
// refetched on load, and the stored copy can predate an acceptance. A Function run
// by a signal must not also run on value changes (L165), so this one has no value
// inputs at all: it turns the signal into a value, and the gate watches the value.
Outputs.tick = Date.now();
